"""Construct the full, jointly trainable local policy without spending rollouts."""
import json,numpy as np,torch
from stable_baselines3 import PPO
from stable_baselines3.common.vec_env import DummyVecEnv
from recover_jump_ppo_batch import SetupOnlyEnv
from controlled_broad_jump import ROOT

def main():
 torch.set_num_threads(1);torch.manual_seed(23);out=ROOT/'deliverables/standing_long_jump_learning';definition=json.loads((ROOT/'results/controlled_broad_jump/full_local_setup_smoke/environment.json').read_text());n=len(definition['actions']);obs=np.array(definition['observation'],np.float32);assert n==43;env=DummyVecEnv([lambda:SetupOnlyEnv(obs,n)]);model=PPO('MlpPolicy',env,learning_rate=.001,n_steps=8,batch_size=8,n_epochs=4,gamma=1.,gae_lambda=1.,clip_range=.15,ent_coef=.001,target_kl=.02,policy_kwargs=dict(net_arch=dict(pi=[32,32],vf=[32,32]),activation_fn=torch.nn.Tanh,log_std_init=float(np.log(.08))),device='cpu',seed=23,verbose=0)
 with torch.no_grad():model.policy.action_net.weight.zero_();model.policy.action_net.bias.zero_()
 action,_=model.predict(obs,deterministic=True);assert np.max(abs(action))==0;assert all(p.requires_grad for p in model.policy.parameters());assert model.policy.log_std.shape==(43,);std=model.policy.log_std.detach().exp().numpy();assert np.allclose(std,.08,atol=1e-7);model.save(out/'full_local_policy_initial');report=dict(status='initialized_not_trained',actor=[7,32,32,43],critic=[7,32,32,1],activation='Tanh',distribution='Diagonal Gaussian with 43 learnable standard deviations',initial_normalized_std=std.tolist(),all_posture_timing_outputs_trainable=True,initial_mean_action_zero=True,training_episodes=0,checkpoint='full_local_policy_initial.zip',constraints='Fixed body, inertia, virtual capacity and contact formulation. Small normalized excursions with native ROM and phase bounds.',parameters=[a['key']for a in definition['actions']],convergence_guaranteed=False,initialization_does_not_establish_normal_human_performance=True);(out/'full_local_policy_initial.json').write_text(json.dumps(report,indent=2));setup=json.loads((out/'full_local_learning_setup.json').read_text());setup['policy_initialization']=report;setup['replay_tolerance_m_s']=1e-8;setup['baseline_zero_action_preserves_takeoff_within_tolerance']=setup.pop('baseline_zero_action_preserves_takeoff_within_1e8_tolerance',setup.get('baseline_zero_action_preserves_takeoff_within_tolerance',False));(out/'full_local_learning_setup.json').write_text(json.dumps(setup,indent=2));print('FULL_POLICY_INITIALIZED',n,'all trainable; no rollouts trained',flush=True)
if __name__=='__main__':main()
